{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "MEDIUM",
      "explanation": "The launch template does not specify block device mappings with encryption enabled. By default, EBS volumes created from this template may not be encrypted at rest, exposing sensitive data if the underlying storage is compromised."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_template.changeme_simple_asg_launch_template_nlb",
      "severity": "HIGH",
      "explanation": "The metadata options are not configured to enforce IMDSv2 (HTTP tokens). This allows instances to respond to unauthenticated requests to the Instance Metadata Service (IMDS), making them vulnerable to Server-Side Request Forgery (SSRF) attacks that can steal IAM credentials."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"changeme_simple_asg_launch_template_nlb\" {\n  name                   = \"changeme-simple-asg-launch-template-nlb\"\n  image_id               = data.aws_ami.changeme_amazon_nlb_ami.id\n  instance_type          = \"t2.micro\"\n  vpc_security_group_ids = [aws_security_group.changeme_nlb_aws_security_group.id]\n  user_data              = filebase64(\"${path.module}/user_data.sh\")\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  block_device_mappings {\n    device_name = \"/dev/xvda\"\n    ebs {\n      encrypted = true\n    }\n  }\n}",
  "fix_summary": "Added `metadata_options` to enforce IMDSv2 (`http_tokens = \"required\"`) and added `block_device_mappings` with `encrypted = true` for the root volume to ensure data at rest is encrypted."
}
